INSERT INTO training_screens (screen_code, module_name, title, bullets, note, table_data, voice_text, audio_file, coins, bonus_coins, timer_seconds, is_critical, sort_order) VALUES ($q$1.1$q$, $q$GİRİŞ$q$, $q$Hassas Metroloji Yolculuğu$q$, $q$["Ece Kalibrasyon Oryantasyon Eğitimi", "Ölçümün ve Güvenin İzinde"]$q$::jsonb, $q$$q$, NULL, $q$Merhaba! Ece Kalibrasyon ailesine hoş geldin! Laf aramızda kalmasın herkes duysun; son derece hassas, dikkat isteyen ama bir o kadar da gurur verici bir mesleğe ilk adımını attın. İki bin on yılından bu yana İstanbul Sancaktepe merkezimiz, Sakarya ve Antalya şubelerimiz, İzmir ve Muğla-Aydın temsilciliklerimizle sağlık, üretim, yapı ve teknoloji alanlarındaki kuruluşlara hizmet veriyoruz. Biz burada sadece cihaz ölçmüyoruz; ölçüm sonuçlarına duyulan güveni koruyoruz. Hazırsan ilk görevine başlayalım!$q$, $q$s00.mp3$q$, 100, 0, 0, FALSE, 1) ON CONFLICT (screen_code) DO UPDATE SET module_name = EXCLUDED.module_name, title = EXCLUDED.title, bullets = EXCLUDED.bullets, note = EXCLUDED.note, table_data = EXCLUDED.table_data, voice_text = EXCLUDED.voice_text, audio_file = EXCLUDED.audio_file, coins = EXCLUDED.coins, bonus_coins = EXCLUDED.bonus_coins, timer_seconds = EXCLUDED.timer_seconds, is_critical = EXCLUDED.is_critical, sort_order = EXCLUDED.sort_order;
INSERT INTO training_questions (training_screen_id, sort_order, question_text, options, correct_index, explanation, coins) VALUES ((SELECT training_screen_id FROM training_screens WHERE screen_code = $q$1.1$q$), 1, $q$Eğitime başlamaya hazır mısın?$q$, $q$["Evet, yolculuğa başlıyorum!"]$q$::jsonb, 0, $q$Harika! Metroli seninle.$q$, 100) ON CONFLICT (training_screen_id, sort_order) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, coins = EXCLUDED.coins;
INSERT INTO training_screens (screen_code, module_name, title, bullets, note, table_data, voice_text, audio_file, coins, bonus_coins, timer_seconds, is_critical, sort_order) VALUES ($q$1.2$q$, $q$MODÜL 1 · KALİTE KÜLTÜRÜ$q$, $q$ISO 17025 ve Kalite Politikası$q$, $q$["TÜRKAK akreditasyonu · AB-0142-K", "Tarafsızlık", "Gizlilik", "Bağımsızlık"]$q$::jsonb, $q$$q$, NULL, $q$Ece Kalibrasyon, ISO IEC on yedi bin yirmi beş standardına göre TÜRKAK tarafından akredite edilmiş bir laboratuvardır. Başarımızın temeli üç esasa dayanır. Bir: tarafsızlık. Ölçüm sonuçlarımız hiçbir ticari veya kişisel baskıdan etkilenmez. İki: gizlilik. Müşterilerimize ait tüm veriler ve kalibrasyon raporları sır niteliğindedir. Üç: bağımsızlık. Teknik karar süreçlerimizde sadece bilimsel verileri esas alırız.$q$, $q$s01.mp3$q$, 0, 0, 0, FALSE, 2) ON CONFLICT (screen_code) DO UPDATE SET module_name = EXCLUDED.module_name, title = EXCLUDED.title, bullets = EXCLUDED.bullets, note = EXCLUDED.note, table_data = EXCLUDED.table_data, voice_text = EXCLUDED.voice_text, audio_file = EXCLUDED.audio_file, coins = EXCLUDED.coins, bonus_coins = EXCLUDED.bonus_coins, timer_seconds = EXCLUDED.timer_seconds, is_critical = EXCLUDED.is_critical, sort_order = EXCLUDED.sort_order;
INSERT INTO training_screens (screen_code, module_name, title, bullets, note, table_data, voice_text, audio_file, coins, bonus_coins, timer_seconds, is_critical, sort_order) VALUES ($q$1.3$q$, $q$MODÜL 1 · KALİTE KÜLTÜRÜ$q$, $q$Akreditasyon Ne Söyler, Ne Söylemez?$q$, $q$["Akreditasyon = yayımlanmış kapsamla sınırlı yetkinlik", "Sonuçlar hatasız olduğunun garantisi değildir", "Hizmet sunmak ≠ akreditasyon kapsamında olmak", "Kapsam: güncel TÜRKAK eki ve rapordan doğrulanır"]$q$::jsonb, $q$Doğru/yanlış kartları: her biri 50 Ece-Coin.$q$, NULL, $q$Akreditasyon, laboratuvarın belirlenmiş faaliyetleri yetkinlikle yürütmek için değerlendirilmiş olduğunu gösterir. Bir hizmeti sunuyor olmamız, o hizmetin otomatik olarak akreditasyon kapsamında olduğu anlamına gelmez. Teklif ve rapor hazırlarken güncel kapsamı kontrol etmek hepimizin sorumluluğudur.$q$, $q$s02.mp3$q$, 150, 0, 0, FALSE, 3) ON CONFLICT (screen_code) DO UPDATE SET module_name = EXCLUDED.module_name, title = EXCLUDED.title, bullets = EXCLUDED.bullets, note = EXCLUDED.note, table_data = EXCLUDED.table_data, voice_text = EXCLUDED.voice_text, audio_file = EXCLUDED.audio_file, coins = EXCLUDED.coins, bonus_coins = EXCLUDED.bonus_coins, timer_seconds = EXCLUDED.timer_seconds, is_critical = EXCLUDED.is_critical, sort_order = EXCLUDED.sort_order;
