INSERT INTO training_screens (screen_code, module_name, title, bullets, note, table_data, voice_text, audio_file, coins, bonus_coins, timer_seconds, is_critical, sort_order) VALUES ($q$1.4$q$, $q$MODÜL 1 · KALİTE KÜLTÜRÜ$q$, $q$Tarafsızlık, Gizlilik ve Veri Bütünlüğü$q$, $q$["Sonucu müşteri talebine göre değiştirme", "Kayıtları iz bırakmadan değiştirme", "Başka müşterinin bilgisini paylaşma", "Hata gizlenmez: kaydet, bildir, süreci başlat"]$q$::jsonb, $q$$q$, NULL, $q$Teslim tarihi ne kadar sıkışık olursa olsun, sonucu değiştirmek bir seçenek değildir. Ölçümü ve kayıtları olduğu gibi koru, durumu yetkili kişiye bildir, müşteriyle yalnızca doğrulanmış bilgiyi paylaş. Hata fark edersen gizleme; kaydet ve süreci başlat. Güvenilirlik, laboratuvarın en değerli varlığıdır.$q$, $q$s03.mp3$q$, 150, 0, 0, TRUE, 4) ON CONFLICT (screen_code) DO UPDATE SET module_name = EXCLUDED.module_name, title = EXCLUDED.title, bullets = EXCLUDED.bullets, note = EXCLUDED.note, table_data = EXCLUDED.table_data, voice_text = EXCLUDED.voice_text, audio_file = EXCLUDED.audio_file, coins = EXCLUDED.coins, bonus_coins = EXCLUDED.bonus_coins, timer_seconds = EXCLUDED.timer_seconds, is_critical = EXCLUDED.is_critical, sort_order = EXCLUDED.sort_order;
INSERT INTO training_questions (training_screen_id, sort_order, question_text, options, correct_index, explanation, coins) VALUES ((SELECT training_screen_id FROM training_screens WHERE screen_code = $q$1.4$q$), 1, $q$Müşteri, teslim tarihine yetişmek için uygun olmayan bir ölçüm sonucunu rapordaki değerden farklı yazmanı istiyor. Ne yaparsın?$q$, $q$["İstediği gibi düzenlerim; müşteri memnuniyeti önemli", "Reddeder, kayıtları olduğu gibi korur, kalite sorumlusuna/yöneticiye bildiririm", "Değiştirir ama not düşerim"]$q$::jsonb, 1, $q$Müşteri memnuniyeti, tarafsız ve güvenilir hizmetin yerine geçmez.$q$, 75) ON CONFLICT (training_screen_id, sort_order) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, coins = EXCLUDED.coins;
