INSERT INTO training_screens (screen_code, module_name, title, bullets, note, table_data, voice_text, audio_file, coins, bonus_coins, timer_seconds, is_critical, sort_order) VALUES ($q$2.1$q$, $q$MODÜL 2 · METROLOJİ$q$, $q$Kalibrasyon mı, Ayarlama mı?$q$, $q$["Kalibrasyon: referansla karşılaştır, sapmayı ve belirsizliği belirle", "Ayarlama: göstergeyi fiziksel/yazılımsal düzelt", "Kalibre etmek, ayarlamak demek değildir"]$q$::jsonb, $q$$q$, NULL, $q$Günlük dilde sıkça yapılan bir hatayı çözelim: kalibrasyon bir tamir veya ayarlama işlemi değildir! Kalibrasyon; doğruluğundan emin olunan referans bir cihaz ile müşteri cihazını karşılaştırıp sapmayı ve ölçüm belirsizliğini tespit etme işlemidir. Cihazın göstergesini düzeltmek ise ayarlamadır. Bir cihaz kalibre edildiğinde ayarlanmış olmaz; sadece ne kadar doğru veya yanlış ölçtüğü tescillenmiş olur.$q$, $q$s04.mp3$q$, 150, 0, 0, FALSE, 5) ON CONFLICT (screen_code) DO UPDATE SET module_name = EXCLUDED.module_name, title = EXCLUDED.title, bullets = EXCLUDED.bullets, note = EXCLUDED.note, table_data = EXCLUDED.table_data, voice_text = EXCLUDED.voice_text, audio_file = EXCLUDED.audio_file, coins = EXCLUDED.coins, bonus_coins = EXCLUDED.bonus_coins, timer_seconds = EXCLUDED.timer_seconds, is_critical = EXCLUDED.is_critical, sort_order = EXCLUDED.sort_order;
