INSERT INTO training_screens (screen_code, module_name, title, bullets, note, table_data, voice_text, audio_file, coins, bonus_coins, timer_seconds, is_critical, sort_order) VALUES ($q$2.2$q$, $q$MODÜL 2 · METROLOJİ$q$, $q$Metrolojik İzlenebilirlik Zinciri$q$, $q$["SI birimleri", "Ulusal metroloji enstitüsü / üst seviye referans", "Laboratuvar referansı", "Müşteri cihazı"]$q$::jsonb, $q$SI birimleri → Ulusal metroloji enstitüsü / uygun üst seviye referans → Laboratuvar referansı → Müşteri cihazı$q$, NULL, $q$Metrolojik izlenebilirlik, bir sonucun belgelenmiş ve kesintisiz bir kalibrasyon zinciriyle bir referansa bağlanabilmesidir. Zincirdeki her adımın katkısı ve belirsizliği değerlendirilir. Doğru zincir, ilgili referans sertifikaları ve akreditasyon kapsamı üzerinden takip edilir.$q$, $q$s05.mp3$q$, 0, 0, 0, FALSE, 6) ON CONFLICT (screen_code) DO UPDATE SET module_name = EXCLUDED.module_name, title = EXCLUDED.title, bullets = EXCLUDED.bullets, note = EXCLUDED.note, table_data = EXCLUDED.table_data, voice_text = EXCLUDED.voice_text, audio_file = EXCLUDED.audio_file, coins = EXCLUDED.coins, bonus_coins = EXCLUDED.bonus_coins, timer_seconds = EXCLUDED.timer_seconds, is_critical = EXCLUDED.is_critical, sort_order = EXCLUDED.sort_order;
INSERT INTO training_screens (screen_code, module_name, title, bullets, note, table_data, voice_text, audio_file, coins, bonus_coins, timer_seconds, is_critical, sort_order) VALUES ($q$2.3$q$, $q$MODÜL 2 · METROLOJİ$q$, $q$Ölçüm Sonucu, Hata ve Düzeltme$q$, $q$["Referans: 100,00 birim · Gösterge: 100,12 birim", "Hata = gösterge − referans = +0,12 birim", "Düzeltme = −0,12 birim", "Terim ve işaret: raporun açıklamasından doğrula"]$q$::jsonb, $q$$q$, NULL, $q$Bir örnek: referans değer yüz birim, cihaz yüz virgül on iki birim gösteriyor. Gösterge eksi referans, artı sıfır virgül on iki birim hata verir; düzeltme ise bunun tersidir, eksi sıfır virgül on iki. Ama sertifikada hangi terimin ve hangi işaretin kullanıldığını her zaman raporun kendi açıklamasından doğrula.$q$, $q$s06.mp3$q$, 100, 0, 0, FALSE, 7) ON CONFLICT (screen_code) DO UPDATE SET module_name = EXCLUDED.module_name, title = EXCLUDED.title, bullets = EXCLUDED.bullets, note = EXCLUDED.note, table_data = EXCLUDED.table_data, voice_text = EXCLUDED.voice_text, audio_file = EXCLUDED.audio_file, coins = EXCLUDED.coins, bonus_coins = EXCLUDED.bonus_coins, timer_seconds = EXCLUDED.timer_seconds, is_critical = EXCLUDED.is_critical, sort_order = EXCLUDED.sort_order;
INSERT INTO training_questions (training_screen_id, sort_order, question_text, options, correct_index, explanation, coins) VALUES ((SELECT training_screen_id FROM training_screens WHERE screen_code = $q$2.3$q$), 1, $q$Referans 100,00 birim, gösterge 100,12 birim. Gösterge − referans kaç birimdir?$q$, $q$["+0,12", "−0,12", "0,00"]$q$::jsonb, 0, $q$Gösterge eksi referans = +0,12 birim (hata).$q$, 50) ON CONFLICT (training_screen_id, sort_order) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, coins = EXCLUDED.coins;
INSERT INTO training_questions (training_screen_id, sort_order, question_text, options, correct_index, explanation, coins) VALUES ((SELECT training_screen_id FROM training_screens WHERE screen_code = $q$2.3$q$), 2, $q$Bu örnekte düzeltme kaç birimdir?$q$, $q$["+0,12", "−0,12", "+100,12"]$q$::jsonb, 1, $q$Düzeltme, hata tahmininin işaretçe tersidir: −0,12 birim.$q$, 50) ON CONFLICT (training_screen_id, sort_order) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, coins = EXCLUDED.coins;
INSERT INTO training_screens (screen_code, module_name, title, bullets, note, table_data, voice_text, audio_file, coins, bonus_coins, timer_seconds, is_critical, sort_order) VALUES ($q$2.4$q$, $q$MODÜL 2 · METROLOJİ$q$, $q$Ölçüm Belirsizliğine İlk Bakış$q$, $q$["Belirsizlik ≠ hata payı ≠ tolerans", "Birleşik standart belirsizlik: u_c", "Genişletilmiş belirsizlik: U = k × u_c", "Örnek: √(0,10² + 0,20²) ≈ 0,224 birim"]$q$::jsonb, $q$$q$, NULL, $q$Ölçüm belirsizliği, hata payı ya da cihazın toleransı değildir. Sonuca atfedilebilecek değerlerin dağılımını anlatır. Bileşenler birleştirilir; sonra kapsama faktörüyle çarpılarak genişletilmiş belirsizlik bulunur. Kapsama faktörü her raporda yazılıdır, ezbere varsayma.$q$, $q$s07.mp3$q$, 150, 0, 0, FALSE, 8) ON CONFLICT (screen_code) DO UPDATE SET module_name = EXCLUDED.module_name, title = EXCLUDED.title, bullets = EXCLUDED.bullets, note = EXCLUDED.note, table_data = EXCLUDED.table_data, voice_text = EXCLUDED.voice_text, audio_file = EXCLUDED.audio_file, coins = EXCLUDED.coins, bonus_coins = EXCLUDED.bonus_coins, timer_seconds = EXCLUDED.timer_seconds, is_critical = EXCLUDED.is_critical, sort_order = EXCLUDED.sort_order;
