INSERT INTO training_questions (training_screen_id, sort_order, question_text, options, correct_index, explanation, coins) VALUES ((SELECT training_screen_id FROM training_screens WHERE screen_code = $q$2.4$q$), 2, $q$Genişletilmiş belirsizlik nasıl bulunur?$q$, $q$["U = k × u_c", "U = u_c + k", "U = u_c / k"]$q$::jsonb, 0, $q$Birleşik standart belirsizlik, kapsama faktörü k ile çarpılır.$q$, 50) ON CONFLICT (training_screen_id, sort_order) DO UPDATE SET question_text = EXCLUDED.question_text, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, coins = EXCLUDED.coins;
