INSERT INTO training_screens (screen_code, module_name, title, bullets, note, table_data, voice_text, audio_file, coins, bonus_coins, timer_seconds, is_critical, sort_order) VALUES ($q$2.6$q$, $q$MODÜL 2 · METROLOJİ$q$, $q$Uygunluk Kararı ve Tolerans$q$, $q$["Hangi özellik ve tolerans sınırı?", "Belirsizlik nasıl hesaba katılıyor?", "Hangi karar kuralı geçerli?", "Sonuç: uygun · uygun değil · karar için yetersiz"]$q$::jsonb, $q$$q$, NULL, $q$Ölçülen değer tolerans içinde diye otomatik olarak uygun demek doğru değildir. Önce hangi özelliğin değerlendirildiğine, belirsizliğin nasıl hesaba katılacağına ve hangi karar kuralının geçerli olduğuna bak. Sonuç, bu kurala göre uygun, uygun değil ya da karar vermek için yetersiz olabilir.$q$, $q$s09.mp3$q$, 200, 0, 0, FALSE, 10) ON CONFLICT (screen_code) DO UPDATE SET module_name = EXCLUDED.module_name, title = EXCLUDED.title, bullets = EXCLUDED.bullets, note = EXCLUDED.note, table_data = EXCLUDED.table_data, voice_text = EXCLUDED.voice_text, audio_file = EXCLUDED.audio_file, coins = EXCLUDED.coins, bonus_coins = EXCLUDED.bonus_coins, timer_seconds = EXCLUDED.timer_seconds, is_critical = EXCLUDED.is_critical, sort_order = EXCLUDED.sort_order;
