INSERT INTO training_screens (screen_code, module_name, title, bullets, note, table_data, voice_text, audio_file, coins, bonus_coins, timer_seconds, is_critical, sort_order) VALUES ($q$3.1 / 3.4$q$, $q$MODÜL 3 · HİZMETLER VE İŞ AKIŞI$q$, $q$Hizmetlerimiz ve Akreditasyon Kapsamı$q$, $q$["Sıcaklık, bağıl nem, basınç", "Kütle, terazi, boyutsal · Antalya: beton ve basma test makineleri", "Validasyon, haritalama, bakım-onarım, eğitim", "Kapsam her işte güncel ekle eşleştirilir"]$q$::jsonb, $q$$q$, NULL, $q$Ece Kalibrasyon; sıcaklık, bağıl nem, basınç, kütle, terazi ve boyutsal kalibrasyon hizmetleri sunar. Antalya şubesinde beton ve basma test makineleri de akreditasyon kapsamındadır. Temiz oda ve taşıma aracı validasyonları, bakım-onarım ve eğitim gibi başka hizmetler de verilir. Her işte cihazı, lokasyonu, yöntemi ve akreditasyon durumunu güncel kapsamla eşleştiririz; emin olmadığımız bir aralık veya hizmet için tahminde bulunmayız.$q$, $q$s10.mp3$q$, 100, 0, 0, FALSE, 11) ON CONFLICT (screen_code) DO UPDATE SET module_name = EXCLUDED.module_name, title = EXCLUDED.title, bullets = EXCLUDED.bullets, note = EXCLUDED.note, table_data = EXCLUDED.table_data, voice_text = EXCLUDED.voice_text, audio_file = EXCLUDED.audio_file, coins = EXCLUDED.coins, bonus_coins = EXCLUDED.bonus_coins, timer_seconds = EXCLUDED.timer_seconds, is_critical = EXCLUDED.is_critical, sort_order = EXCLUDED.sort_order;
