INSERT INTO training_screens (screen_code, module_name, title, bullets, note, table_data, voice_text, audio_file, coins, bonus_coins, timer_seconds, is_critical, sort_order) VALUES ($q$3.2$q$, $q$MODÜL 3 · HİZMETLER VE İŞ AKIŞI$q$, $q$Hizmet Süreci Baştan Sona$q$, $q$["Talep → Teklif ve kapsam teyidi → Cihaz kabulü", "İş emri ve kimliklendirme → Ölçüm", "Teknik gözden geçirme → Rapor", "İade ve geri bildirimden öğrenme"]$q$::jsonb, $q$$q$, NULL, $q$Her iş aynı yolu izler: talebi anla, yapılabilirliği ve kapsamı teyit et, cihazı doğru tanımla, ölçümü onaylı yöntemle yürüt, sonucu gözden geçir, işi kapat ve geri bildirimden öğren. Bu zincirin her halkası, raporun güvenilirliğini oluşturur.$q$, $q$s11.mp3$q$, 150, 0, 0, FALSE, 12) ON CONFLICT (screen_code) DO UPDATE SET module_name = EXCLUDED.module_name, title = EXCLUDED.title, bullets = EXCLUDED.bullets, note = EXCLUDED.note, table_data = EXCLUDED.table_data, voice_text = EXCLUDED.voice_text, audio_file = EXCLUDED.audio_file, coins = EXCLUDED.coins, bonus_coins = EXCLUDED.bonus_coins, timer_seconds = EXCLUDED.timer_seconds, is_critical = EXCLUDED.is_critical, sort_order = EXCLUDED.sort_order;
