INSERT INTO training_screens (screen_code, module_name, title, bullets, note, table_data, voice_text, audio_file, coins, bonus_coins, timer_seconds, is_critical, sort_order) VALUES ($q$3.3$q$, $q$MODÜL 3 · HİZMETLER VE İŞ AKIŞI$q$, $q$Laboratuvar mı, Yerinde mi?$q$, $q$["Taşıma performansı etkiler mi?", "Nakil sırasında hasar riski var mı?", "Sahada referans, enerji, erişim, güvenlik sağlanır mı?", "Karar: teknik gözden geçirme"]$q$::jsonb, $q$$q$, NULL, $q$Laboratuvarda mı, yerinde mi? Cihaz taşınınca performansı değişebilir mi, nakil riski var mı, sahada referans, enerji, erişim ve çevre koşulları sağlanabilir mi? Bu soruların yanıtı teknik gözden geçirmeyle verilir. Yerinde hizmet her cihaz için uygun değildir.$q$, $q$s12.mp3$q$, 100, 0, 0, FALSE, 13) ON CONFLICT (screen_code) DO UPDATE SET module_name = EXCLUDED.module_name, title = EXCLUDED.title, bullets = EXCLUDED.bullets, note = EXCLUDED.note, table_data = EXCLUDED.table_data, voice_text = EXCLUDED.voice_text, audio_file = EXCLUDED.audio_file, coins = EXCLUDED.coins, bonus_coins = EXCLUDED.bonus_coins, timer_seconds = EXCLUDED.timer_seconds, is_critical = EXCLUDED.is_critical, sort_order = EXCLUDED.sort_order;
