INSERT INTO training_screens (screen_code, module_name, title, bullets, note, table_data, voice_text, audio_file, coins, bonus_coins, timer_seconds, is_critical, sort_order) VALUES ($q$3.5$q$, $q$MODÜL 3 · HİZMETLER VE İŞ AKIŞI$q$, $q$Kalibrasyon, Validasyon, Bakım, Ayarlama$q$, $q$["Kalibrasyon: ilişki + belirsizlik", "Validasyon: amaca uygunluğun kanıtı", "Bakım/onarım: işlevi korur veya arızayı giderir", "Ayarlama: göstergeye müdahale"]$q$::jsonb, $q$$q$, NULL, $q$Kalibrasyon, referansla cihaz arasındaki ilişkiyi ve belirsizliği belirler. Validasyon, bir sistemin veya alanın amacına uygunluğunu kabul ölçütleriyle kanıtlar. Bakım ve onarım işlevi korur veya arızayı giderir. Ayarlama ise göstergeye müdahaledir. Bunları birbirine karıştırma; emin değilsen teknik sorumluya yönlendir.$q$, $q$s13.mp3$q$, 150, 0, 0, FALSE, 14) ON CONFLICT (screen_code) DO UPDATE SET module_name = EXCLUDED.module_name, title = EXCLUDED.title, bullets = EXCLUDED.bullets, note = EXCLUDED.note, table_data = EXCLUDED.table_data, voice_text = EXCLUDED.voice_text, audio_file = EXCLUDED.audio_file, coins = EXCLUDED.coins, bonus_coins = EXCLUDED.bonus_coins, timer_seconds = EXCLUDED.timer_seconds, is_critical = EXCLUDED.is_critical, sort_order = EXCLUDED.sort_order;
