INSERT INTO training_screens (screen_code, module_name, title, bullets, note, table_data, voice_text, audio_file, coins, bonus_coins, timer_seconds, is_critical, sort_order) VALUES ($q$4.1$q$, $q$MODÜL 4 · MÜŞTERİ İLETİŞİMİ$q$, $q$Çözüm Ortağı, Hassas Emanet$q$, $q$["Müşteri → Çözüm ortağı", "Cihaz → Hassas emanet", "Saha → Güvenlik ve kalite mevzisi"]$q$::jsonb, $q$$q$, NULL, $q$Laboratuvarımıza gelen bir cihaz veya sahada test ettiğimiz bir sistem sadece metal ve elektronikten ibaret değildir. O cihaz, müşterimizin üretim kalitesine ve kararlarına doğrudan etki eder. Bu yüzden müşterilerimize çözüm ortağı, cihazlarına ise hassas emanet gözüyle bakarız. Onların sorularına doğru, anlaşılır ve bilimsel yanıtlar vermek temel ilkemizdir.$q$, $q$s14.mp3$q$, 0, 0, 0, FALSE, 15) ON CONFLICT (screen_code) DO UPDATE SET module_name = EXCLUDED.module_name, title = EXCLUDED.title, bullets = EXCLUDED.bullets, note = EXCLUDED.note, table_data = EXCLUDED.table_data, voice_text = EXCLUDED.voice_text, audio_file = EXCLUDED.audio_file, coins = EXCLUDED.coins, bonus_coins = EXCLUDED.bonus_coins, timer_seconds = EXCLUDED.timer_seconds, is_critical = EXCLUDED.is_critical, sort_order = EXCLUDED.sort_order;
INSERT INTO training_screens (screen_code, module_name, title, bullets, note, table_data, voice_text, audio_file, coins, bonus_coins, timer_seconds, is_critical, sort_order) VALUES ($q$4.2 / 4.4$q$, $q$MODÜL 4 · MÜŞTERİ İLETİŞİMİ$q$, $q$Müşteri Sorularına Doğru Yanıt$q$, $q$["Teslim süresi → iş emrinden teyit et", "Limit dışı sapma → belirsizlik ve karar kuralıyla birlikte incele", "Yerinde hizmet → teknik ekiple yapılabilirliği teyit et", "Bilmediğini tahmin etme"]$q$::jsonb, $q$$q$, NULL, $q$Müşteri sorularında altın kural şudur: bildiğini açık söyle, bilmediğini tahmin etme. Teslim süresi, uygunluk yorumu ve yerinde hizmet gibi konularda önce kontrollü kaynağı ve teknik sorumluyu devreye al, sonra müşteriye net bir geri dönüş zamanı ver. İyi bir teklif, iyi sorularla başlar. Cihazı, ölçüm aralığını, toleransı, lokasyonu ve akreditasyon beklentisini baştan netleştirirsen hem müşteri hem laboratuvar zaman kazanır.$q$, $q$s15.mp3$q$, 200, 0, 0, FALSE, 16) ON CONFLICT (screen_code) DO UPDATE SET module_name = EXCLUDED.module_name, title = EXCLUDED.title, bullets = EXCLUDED.bullets, note = EXCLUDED.note, table_data = EXCLUDED.table_data, voice_text = EXCLUDED.voice_text, audio_file = EXCLUDED.audio_file, coins = EXCLUDED.coins, bonus_coins = EXCLUDED.bonus_coins, timer_seconds = EXCLUDED.timer_seconds, is_critical = EXCLUDED.is_critical, sort_order = EXCLUDED.sort_order;
