INSERT INTO training_screens (screen_code, module_name, title, bullets, note, table_data, voice_text, audio_file, coins, bonus_coins, timer_seconds, is_critical, sort_order) VALUES ($q$4.3 / 4.5$q$, $q$MODÜL 4 · MÜŞTERİ İLETİŞİMİ$q$, $q$Zor Görüşmelerde İletişim$q$, $q$["Sonuç ticari talebe göre değişmez", "Başka müşterilerin bilgisi paylaşılmaz", "Kalibrasyon ≠ ayarlama", "Çözüm sun: teknik inceleme, resmi süreç"]$q$::jsonb, $q$$q$, NULL, $q$Zor görüşmelerde sakin, net ve tutarlı kal. Sonucu ticari talebe göre değiştirmeyiz. Başka müşterilerin bilgisini paylaşmayız. Kalibrasyonla ayarlamayı karıştırmayız. Bunu söylerken de çözüm sun: teknik ekiple birlikte veriyi gözden geçirmeyi ve resmi süreci başlatmayı teklif et.$q$, $q$s16.mp3$q$, 300, 0, 0, FALSE, 17) ON CONFLICT (screen_code) DO UPDATE SET module_name = EXCLUDED.module_name, title = EXCLUDED.title, bullets = EXCLUDED.bullets, note = EXCLUDED.note, table_data = EXCLUDED.table_data, voice_text = EXCLUDED.voice_text, audio_file = EXCLUDED.audio_file, coins = EXCLUDED.coins, bonus_coins = EXCLUDED.bonus_coins, timer_seconds = EXCLUDED.timer_seconds, is_critical = EXCLUDED.is_critical, sort_order = EXCLUDED.sort_order;
