INSERT INTO training_screens (screen_code, module_name, title, bullets, note, table_data, voice_text, audio_file, coins, bonus_coins, timer_seconds, is_critical, sort_order) VALUES ($q$5.1$q$, $q$MODÜL 5 · ÇALIŞAN REHBERİ VE İSG$q$, $q$Yıllık Ücretli İzin Hakları$q$, $q$["1–5 yıl (5 dahil): 14 gün", "5 yıldan fazla, 15 yıldan az: 20 gün", "15 yıl ve üzeri: 26 gün", "Bakiye ve özel durum: İnsan Kaynakları"]$q$::jsonb, $q$Süreler iş günü değil gündür. 18 yaşından küçük ve 50 yaşından büyük çalışanlarda asgari süre 20 gündür. Bakiye ve özel durumlar için İnsan Kaynakları ve güncel mevzuat esas alınır.$q$, $q$[["Kıdem süresi", "Yıllık ücretli izin"], ["1 yıl – 5 yıl (5 yıl dahil)", "14 gün"], ["5 yıldan fazla – 15 yıldan az", "20 gün"], ["15 yıl ve üzeri", "26 gün"]]$q$::jsonb, $q$İş Kanunu'na göre yıllık ücretli izin süresi, bir ila beş yıl arasında, beş yıl dahil, on dört gün; beş yıldan fazla, on beş yıldan az olanlarda yirmi gün; on beş yıl ve üzerinde yirmi altı gündür. Bakiyeni ve özel durumları İnsan Kaynakları'ndan teyit et.$q$, $q$s17.mp3$q$, 100, 0, 0, FALSE, 18) ON CONFLICT (screen_code) DO UPDATE SET module_name = EXCLUDED.module_name, title = EXCLUDED.title, bullets = EXCLUDED.bullets, note = EXCLUDED.note, table_data = EXCLUDED.table_data, voice_text = EXCLUDED.voice_text, audio_file = EXCLUDED.audio_file, coins = EXCLUDED.coins, bonus_coins = EXCLUDED.bonus_coins, timer_seconds = EXCLUDED.timer_seconds, is_critical = EXCLUDED.is_critical, sort_order = EXCLUDED.sort_order;
