INSERT INTO training_screens (screen_code, module_name, title, bullets, note, table_data, voice_text, audio_file, coins, bonus_coins, timer_seconds, is_critical, sort_order) VALUES ($q$5.2 / 5.3$q$, $q$MODÜL 5 · ÇALIŞAN REHBERİ VE İSG$q$, $q$Güvenli Çalışma ve Saha Planı$q$, $q$["Kapsam, saha kuralları, acil durum bilgisi", "Ekipmanı gözle denetle", "Basınç / elektrik düzeneğini güvenle kur", "Uygun KKD · Şüphede dur ve danış"]$q$::jsonb, $q$$q$, NULL, $q$İşe başlamadan önce altı adımı uygula: kapsamı ve saha kurallarını teyit et, riskleri ve acil durum bilgisini kontrol et, ekipmanı gözle denetle, basınç ve elektrik düzeneğini güvenle kur, uygun koruyucu donanımı giy, beklenmeyen bir durumda işi durdur ve bildir. Şüphen varsa dur ve danış. Hiçbir ölçüm, bir kazaya değmez.$q$, $q$s18.mp3$q$, 400, 0, 0, TRUE, 19) ON CONFLICT (screen_code) DO UPDATE SET module_name = EXCLUDED.module_name, title = EXCLUDED.title, bullets = EXCLUDED.bullets, note = EXCLUDED.note, table_data = EXCLUDED.table_data, voice_text = EXCLUDED.voice_text, audio_file = EXCLUDED.audio_file, coins = EXCLUDED.coins, bonus_coins = EXCLUDED.bonus_coins, timer_seconds = EXCLUDED.timer_seconds, is_critical = EXCLUDED.is_critical, sort_order = EXCLUDED.sort_order;
