INSERT INTO training_screens (screen_code, module_name, title, bullets, note, table_data, voice_text, audio_file, coins, bonus_coins, timer_seconds, is_critical, sort_order) VALUES ($q$6.1$q$, $q$MODÜL 6 · FİNAL GÖREVİ$q$, $q$Akreditasyon Günü$q$, $q$["Kontrol 1: Çevre koşulları kayıtları", "Kontrol 2: Referansların geçerli izlenebilirliği", "Kontrol 3: Sonuç, belirsizlik, karar kuralı", "İddiayı kanıtla destekle"]$q$::jsonb, $q$$q$, NULL, $q$TÜRKAK denetçisi kapıda! Panik yok. Her kontrol noktasında iddiayı kanıtla destekle: koşul kayıtlarını, referansların izlenebilirliğini, sonuç, belirsizlik ve karar kuralını göster. Denetim, hazırlıklı ve dürüst bir laboratuvar için bir fırsattır.$q$, $q$s19.mp3$q$, 500, 50, 180, FALSE, 20) ON CONFLICT (screen_code) DO UPDATE SET module_name = EXCLUDED.module_name, title = EXCLUDED.title, bullets = EXCLUDED.bullets, note = EXCLUDED.note, table_data = EXCLUDED.table_data, voice_text = EXCLUDED.voice_text, audio_file = EXCLUDED.audio_file, coins = EXCLUDED.coins, bonus_coins = EXCLUDED.bonus_coins, timer_seconds = EXCLUDED.timer_seconds, is_critical = EXCLUDED.is_critical, sort_order = EXCLUDED.sort_order;
