INSERT INTO training_screens (screen_code, module_name, title, bullets, note, table_data, voice_text, audio_file, coins, bonus_coins, timer_seconds, is_critical, sort_order) VALUES ($q$6.3$q$, $q$MODÜL 6 · FİNAL GÖREVİ$q$, $q$Final Vaka: Uygun Olmayan Sonuç$q$, $q$["Ham veri ve kimliği doğrula", "Belirsizlik + şartname + karar kuralı", "Teknik gözden geçirme · veriyi değiştirme", "Sonucu tarafsız bir dille ilet"]$q$::jsonb, $q$$q$, NULL, $q$Sevkiyat yaklaşıyor, müşteri sabırsız, ama sonuç tolerans dışında görünüyor. Doğru yol bellidir: ham veriyi ve kimliği doğrula, belirsizliği ve karar kuralını birlikte değerlendir, teknik gözden geçirmeyi başlat ve sonucu tarafsız bir dille ilet. Veriyi asla değiştirme.$q$, $q$s20.mp3$q$, 400, 0, 0, TRUE, 21) ON CONFLICT (screen_code) DO UPDATE SET module_name = EXCLUDED.module_name, title = EXCLUDED.title, bullets = EXCLUDED.bullets, note = EXCLUDED.note, table_data = EXCLUDED.table_data, voice_text = EXCLUDED.voice_text, audio_file = EXCLUDED.audio_file, coins = EXCLUDED.coins, bonus_coins = EXCLUDED.bonus_coins, timer_seconds = EXCLUDED.timer_seconds, is_critical = EXCLUDED.is_critical, sort_order = EXCLUDED.sort_order;
