INSERT INTO training_screens (screen_code, module_name, title, bullets, note, table_data, voice_text, audio_file, coins, bonus_coins, timer_seconds, is_critical, sort_order) VALUES ($q$7$q$, $q$MODÜL 7 · YETKİNLİK$q$, $q$Oryantasyondan Yetkilendirmeye$q$, $q$["Bilgi edinme", "Gözetimli uygulama", "Yetkinlik değerlendirmesi", "Yetkilendirme · Süreklilik"]$q$::jsonb, $q$Yetkinlik aşamaları: Bilgi edinme → Gözetimli uygulama → Yetkinlik değerlendirmesi → Yetkilendirme → Süreklilik.$q$, NULL, $q$Bu oryantasyonu tamamlamak, tek başına bir ölçüm yönteminde bağımsız çalışma yetkisi vermez. Yetkinlik beş aşamada kazanılır: bilgi edinme, gözetimli uygulama, yetkinlik değerlendirmesi, yetkilendirme ve süreklilik. Her aşamada eğitici ve yönetici sana destek olur.$q$, $q$s21.mp3$q$, 200, 0, 0, FALSE, 22) ON CONFLICT (screen_code) DO UPDATE SET module_name = EXCLUDED.module_name, title = EXCLUDED.title, bullets = EXCLUDED.bullets, note = EXCLUDED.note, table_data = EXCLUDED.table_data, voice_text = EXCLUDED.voice_text, audio_file = EXCLUDED.audio_file, coins = EXCLUDED.coins, bonus_coins = EXCLUDED.bonus_coins, timer_seconds = EXCLUDED.timer_seconds, is_critical = EXCLUDED.is_critical, sort_order = EXCLUDED.sort_order;
