INSERT INTO training_screens (screen_code, module_name, title, bullets, note, table_data, voice_text, audio_file, coins, bonus_coins, timer_seconds, is_critical, sort_order) VALUES ($q$8$q$, $q$MODÜL 8 · TERİMLER VE KAYNAKLAR$q$, $q$Ortak Dilimiz ve Doğru Kaynak$q$, $q$["Metroloji · Kalibrasyon · Ayarlama", "Doğrulama · Validasyon · Belirsizlik", "İzlenebilirlik · Akreditasyon kapsamı · Karar kuralı", "Emin değilsen kontrollü dokümana başvur"]$q$::jsonb, $q$$q$, NULL, $q$Son durak: terimler ve kaynaklar. Metroloji, kalibrasyon, ayarlama, doğrulama, validasyon, belirsizlik, izlenebilirlik, akreditasyon kapsamı ve karar kuralı; bunlar ortak dilimiz. Bilgiden emin olmadığında güncel kontrollü dokümana, TÜRKAK kapsam ekine veya doküman sahibine başvur.$q$, $q$s22.mp3$q$, 200, 0, 0, FALSE, 23) ON CONFLICT (screen_code) DO UPDATE SET module_name = EXCLUDED.module_name, title = EXCLUDED.title, bullets = EXCLUDED.bullets, note = EXCLUDED.note, table_data = EXCLUDED.table_data, voice_text = EXCLUDED.voice_text, audio_file = EXCLUDED.audio_file, coins = EXCLUDED.coins, bonus_coins = EXCLUDED.bonus_coins, timer_seconds = EXCLUDED.timer_seconds, is_critical = EXCLUDED.is_critical, sort_order = EXCLUDED.sort_order;
