INSERT INTO training_screens (screen_code, module_name, title, bullets, note, table_data, voice_text, audio_file, coins, bonus_coins, timer_seconds, is_critical, sort_order) VALUES ($q$6.2$q$, $q$KAPANIŞ$q$, $q$Tebrikler! Görev Tamamlandı$q$, $q$["Bu eğitim temel kavramları tanıtır", "Bağımsız çalışma yetkisi vermez", "Gözetimli uygulama ve yetkinlik değerlendirmesi ayrıca yapılır", "Güvenli, tarafsız ve dikkatli çalışmalar!"]$q$::jsonb, $q$$q$, NULL, $q$Tebrikler, oryantasyon öğrenme yolculuğunu tamamladın. Bu eğitim temel kavramları ve doğru eskalasyon adımlarını tanıtır; bağımsız çalışma yetkisi vermez. Her yöntem için gerekli gözetimli uygulama ve yetkinlik değerlendirmesi ayrıca tamamlanır. Laboratuvarda ve sahada güvenli, tarafsız ve dikkatli çalışmalar dileriz.$q$, $q$s23.mp3$q$, 0, 0, 0, FALSE, 24) ON CONFLICT (screen_code) DO UPDATE SET module_name = EXCLUDED.module_name, title = EXCLUDED.title, bullets = EXCLUDED.bullets, note = EXCLUDED.note, table_data = EXCLUDED.table_data, voice_text = EXCLUDED.voice_text, audio_file = EXCLUDED.audio_file, coins = EXCLUDED.coins, bonus_coins = EXCLUDED.bonus_coins, timer_seconds = EXCLUDED.timer_seconds, is_critical = EXCLUDED.is_critical, sort_order = EXCLUDED.sort_order;
